+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const __dirname = path.dirname(fileURLToPath(import.meta.url));
+const DATA_DIR = path.join(__dirname, 'data');
+
+const TOOL_NAME = 'file_metadata';
+
+export async function listTools() {
+  return [
+    {
+      name: TOOL_NAME,
+      description:
+        'Return metadata (relative path, byte size, lowercase extension) for a file under the data directory. Does not expose file contents.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          path: {
+            type: 'string',
+            description: 'Relative path of the file within the data directory.',
+          },
+        },
+        required: ['path'],
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== TOOL_NAME) {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const allowed = new Set(['path']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+
+  const pathArg = args.path;
+  if (typeof pathArg !== 'string' || pathArg.trim().length === 0) {
+    throw new Error('path is required');
+  }
+
+  // Resolve under the data directory and reject traversal/absolute escapes.
+  const target = path.resolve(DATA_DIR, pathArg);
+  const rel = path.relative(DATA_DIR, target);
+  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
+    throw new Error('Path traversal not allowed');
+  }
+
+  let stat;
+  try {
+    stat = await fs.stat(target);
+  } catch (_e) {
+    throw new Error(`File not found: ${pathArg}`);
+  }
+  if (!stat.isFile()) {
+    throw new Error(`Not a file: ${pathArg}`);
+  }
+
+  const ext = path.extname(target).toLowerCase();
+  const text = `path: ${rel}\nsize: ${stat.size} bytes\nextension: ${ext}`;
+
+  return {
+    content: [{ type: 'text', text }],
+  };
+}
